// livefire — ASSEMBLED universal workflow. DO NOT EDIT BY HAND.
// Generated by build.mjs from src/adapter.js + src/budget.js + src/inventory-view.js + presets/* + src/harness-core.js.
// The full preset REGISTRY is inlined; the controller passes a small cfg.preset string.
// Edit the sources and re-run `node build.mjs`.

export const meta = {
  name: 'livefire',
  description: 'Security/feature verification: live authz-model inventory → static lenses → 3-actor live-DB prover → adversarial cross-modal → root-cause family sweep. Stack-agnostic via presets.',
  phases: [
    { title: 'Inventory', detail: 'dump the live authz model (grants/policies or route->guard map) + secret surfaces' },
    { title: 'Static', detail: 'one reviewer per lens over the whole reachable surface' },
    { title: 'Prove', detail: 'live 3-actor matrix (anon/outsider/wrong-role), direct ground-truth read' },
    { title: 'Verify', detail: 'refute each candidate + cross-modal confirm' },
    { title: 'Sweep', detail: 'root-cause family sweep across every unit' },
    { title: 'Critic', detail: 'what was not covered' },
  ],
}

// ════════════════════════ inlined: src/inventory.js ════════════════════════
// livefire — shared inventory shapes: the Postgres catalog dump + the app-tier units map.
//
// The rule-4 authz-model dump for ANY Postgres target: SECURITY DEFINER EXECUTE grants +
// RLS policies + zero-policy tables + secret/PII columns. Used verbatim by the `supabase`
// preset AND by the GENERIC adapter's fallback — so a generic run against a Postgres DB is
// NEVER blind on the catalog (that blindness was the livefire⟷verify-feature divergence:
// generic returned policies:0 while the supabase-native harness dumped the full catalog).
// Non-Postgres stacks don't use this; their preset supplies its own inventory.

const POSTGRES_INVENTORY_SQL =
  `Run against the live DB and return structured results (run each query STANDALONE / autocommit — never in one shared transaction, since an expected "permission denied" aborts the tx and truncates the dump):
   (a) every SECURITY DEFINER function + which roles hold EXECUTE — e.g.
       SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.prosecdef,
              has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_exec,
              has_function_privilege('authenticated', p.oid, 'EXECUTE') AS authed_exec
       FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosecdef;
   (b) every RLS policy USING + WITH CHECK — SELECT schemaname,tablename,policyname,cmd,qual,with_check FROM pg_policies WHERE schemaname='public';
   (c) RLS-enabled tables with zero policies;
   (d) columns holding secrets/PII (tokens, raw payloads, refresh tokens, oauth secrets, private free-text fields) and that table's SELECT policy breadth;
   (e) catalog_counts — the ground-truth totals your lists must match:
       SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosecdef;   -- → privileged_units
       SELECT count(*) FROM pg_policies WHERE schemaname='public';                                                          -- → policies`

// The ground-truth totals an inventory must match. The pipeline compares the enumerated lists
// against these and re-runs a short dump once (a truncated dump — e.g. an aborted transaction —
// looks exactly like a small app otherwise). Shared by every inventory shape.
const CATALOG_COUNTS_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: { privileged_units: { type: 'number' }, policies: { type: 'number' } },
  required: ['privileged_units', 'policies'],
}

const POSTGRES_INVENTORY_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    secdef_funcs: { type: 'array', items: { type: 'object', additionalProperties: false,
      properties: { name: { type: 'string' }, args: { type: 'string' }, anon_exec: { type: 'boolean' }, authed_exec: { type: 'boolean' }, note: { type: 'string' } },
      required: ['name', 'args', 'anon_exec', 'authed_exec', 'note'] } },
    policies: { type: 'array', items: { type: 'object', additionalProperties: false,
      properties: { table: { type: 'string' }, cmd: { type: 'string' }, using: { type: 'string' }, with_check: { type: 'string' }, flag: { type: 'string' } },
      required: ['table', 'cmd', 'using', 'with_check', 'flag'] } },
    zero_policy_tables: { type: 'array', items: { type: 'string' } },
    secret_columns: { type: 'array', items: { type: 'object', additionalProperties: false,
      properties: { table: { type: 'string' }, column: { type: 'string' }, select_breadth: { type: 'string' } },
      required: ['table', 'column', 'select_breadth'] } },
    catalog_counts: CATALOG_COUNTS_SCHEMA,
  },
  required: ['secdef_funcs', 'policies', 'zero_policy_tables', 'secret_columns', 'catalog_counts'],
}

const POSTGRES_INVENTORY_FLAG_HINT =
  'Flag: every secdef function with anon_exec or authed_exec true; every USING-only UPDATE policy (with_check empty) and every WITH CHECK weaker than its USING; RLS-enabled zero-policy tables; secret/PII columns whose SELECT policy is broader than the owner.'

// How to RUN a Postgres catalog dump robustly (the psql-specific half of the inventory stage).
// Lives here, not in the pipeline, so the core stays stack-agnostic.
const POSTGRES_INVENTORY_EXECUTION =
  `• Run each catalog query INDEPENDENTLY in AUTOCOMMIT (a separate \`psql -c "..."\` invocation per query — if \`psql\` is not installed on the host, run it inside the DB container, e.g. \`docker exec <db-container> psql -U postgres -c "..."\`), never inside one BEGIN/transaction and never as a multi-statement batch — an expected error (e.g. "permission denied" on a locked table, or one bad row) ABORTS a transaction and makes every later query "ignored until end of transaction", silently truncating the dump.\n` +
  `• Expect a mature app to have dozens of privileged functions and dozens–hundreds of policies. Sanity-check: SELECT count(*) FROM pg_policies WHERE schemaname='public' must equal the number of policy rows you enumerated (report it in catalog_counts).`

// The app-tier inventory (authz in code / in a rules DSL / in a CMS permission table): every
// route/handler/rule/permission is a UNIT with its guard and whether a wrong actor reaches it.
// `reachable_by_wrong_actor` is what the pipeline's wrong_actor_reachable summary counts.
const APP_TIER_UNITS_INSTRUCTION =
  'Return EVERY unit (route / handler / resolver / rule / permission row / scheduled job) in units[] with: name, kind, location (file:line or table/row), guard (the exact check protecting it, or "none"), reachable_by_wrong_actor (true if anon, an outsider or a wrong-role insider can reach the protected action/data given that guard), note. Put secret/PII fields and who can read them in secret_columns[]. In catalog_counts, report the TOTAL number of units you found by a mechanical count (e.g. the number of route registrations / rule blocks / permission rows) as privileged_units, and policies = 0 unless the stack also has DB row policies.'

const APP_TIER_INVENTORY_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    units: { type: 'array', items: { type: 'object', additionalProperties: false,
      properties: { name: { type: 'string' }, kind: { type: 'string' }, location: { type: 'string' }, guard: { type: 'string' }, reachable_by_wrong_actor: { type: 'boolean' }, note: { type: 'string' } },
      required: ['name', 'kind', 'location', 'guard', 'reachable_by_wrong_actor', 'note'] } },
    policies: { type: 'array', items: { type: 'object', additionalProperties: true } },
    secret_columns: { type: 'array', items: { type: 'object', additionalProperties: false,
      properties: { table: { type: 'string' }, column: { type: 'string' }, select_breadth: { type: 'string' } },
      required: ['table', 'column', 'select_breadth'] } },
    notes: { type: 'array', items: { type: 'string' } },
    catalog_counts: CATALOG_COUNTS_SCHEMA,
  },
  required: ['units', 'secret_columns', 'notes', 'catalog_counts'],
}

// Permissive schema for the GENERIC adapter's fallback: accepts the Postgres catalog shape
// (secdef_funcs/policies/…) when the target is Postgres, OR a units[] map for any other stack.
// additionalProperties:true + no required so the agent fills whatever the target actually has.
const GENERIC_INVENTORY_SCHEMA = {
  type: 'object', additionalProperties: true,
  properties: {
    secdef_funcs: { type: 'array', items: { type: 'object', additionalProperties: true } },
    policies: { type: 'array', items: { type: 'object', additionalProperties: true } },
    zero_policy_tables: { type: 'array', items: { type: 'string' } },
    secret_columns: { type: 'array', items: { type: 'object', additionalProperties: true } },
    units: { type: 'array', items: { type: 'object', additionalProperties: true,
      properties: { name: { type: 'string' }, guard: { type: 'string' }, reachable_by_wrong_actor: { type: 'boolean' } },
      required: ['name', 'guard', 'reachable_by_wrong_actor'] } },
    notes: { type: 'array', items: { type: 'string' } },
    catalog_counts: CATALOG_COUNTS_SCHEMA,
  },
  required: ['catalog_counts'],
}


// ════════════════════════ inlined: src/adapter.js ════════════════════════
// livefire — the VerifyAdapter contract.
//
// livefire's method is stack-agnostic: read the code · run the exploit · walk the user story ·
// three-actor matrix · cross-modal confirm · root-cause family sweep. Only TWO things are
// stack-specific — how you enumerate the app's authz model, and how you build the three
// attacker clients + read ground truth. Both live behind this one interface. A preset is just
// an object implementing it. Nothing in the pipeline (src/harness-core.js) references Postgres,
// Supabase, or any stack directly — it only reads the fields below.
//
// IMPORTANT: in the Workflow model the pipeline does NOT execute SQL or open DB clients itself
// — its subagents do. So an adapter's fields are mostly INSTRUCTIONS (prompt fragments) + SQL
// text + a JSON schema for the structured dump. The adapter DESCRIBES; the agent DOES. That is
// why `db` / `actors` / `inventorySql` are strings: they are handed to an agent that has shell
// + DB access. Fields may also be a function `(repo) => string` for dynamic presets.
//
// ── The contract ──────────────────────────────────────────────────────────────────
// id            string    unique preset id, e.g. 'supabase', 'rails-pg', 'spring'.
// detect        (repo) => boolean   OPTIONAL. Given a light repo probe (see RepoProbe),
//                         return true if this preset fits. Used by auto-detect. First match
//                         wins; order presets most-specific first in the registry.
// repoContext   string    one paragraph: the app, its tenancy/ownership model, what "wrong
//                         actor" means here. Prepended to every agent's context.
// db            string    how an agent reaches the live LOCAL/disposable DB + the admin /
//                         service-role client used to PLANT fixtures and run the confirming
//                         SELECT (the evidence). MUST point at a throwaway DB — see the
//                         livefire safety guard; never a managed/prod host.
// actors        string    how to construct the three attacker clients — (1) ANON (no session),
//                         (2) OUTSIDER (authenticated, zero membership), (3) INSIDER-WRONG-ROLE
//                         (authenticated, wrong role in the target tenant) — plus the admin
//                         client. For stacks where authz is in code (Spring/Rails), this is
//                         "mint a JWT/session for each" rather than DB keys.
// inventorySql  string    what to dump so the authz model becomes DATA. For Postgres/RLS this
//                         is pg_proc EXECUTE grants + pg_policies. For app-tier-authz stacks it
//                         is "enumerate every route -> its guard; every ORM query missing a
//                         tenant filter" and the DB-grant part degrades to n/a (say so).
// inventorySchema object   JSON Schema for the structured inventory dump. Stack-specific shape.
//                         The pipeline treats it opaquely — it only forwards the dumped JSON.
// testCmd       string    the project's test runner, e.g. 'npm test', 'pytest', 'bundle exec rspec'.
// lenses        [{key,prompt}]  the static-review lenses. Sensible universal defaults live in
//                         DEFAULT_LENSES below; a preset overrides only what its stack changes.
// emitTestHint  string    OPTIONAL. how a RED-first regression test is written for this stack
//                         (framework + how to pair the assertion with a direct ground-truth
//                         read). Defaults to a generic description if omitted.
// inventoryExecution string OPTIONAL. how to RUN the dump robustly (e.g. one psql per query in
//                         autocommit). The pipeline itself never names a tool.
// guardExamples string    OPTIONAL. the kinds of existing checks a verifier must look for before
//                         confirming a candidate (RLS/REVOKE/trigger for Postgres; middleware /
//                         policy / query scope for app-tier stacks).
// credentialsHint string  OPTIONAL. where the LOCAL stack's credentials come from.
// proverTargets string    OPTIONAL. what the prover must attack from all three actors.
// scopeUnits    string    OPTIONAL. how a whole-surface pass names "everything" on this stack.
//
// Per-repo OVERRIDES (cfg / livefire.config.mjs, on top of a preset — this is how a project adds
// what the preset can't know: its tenancy model, its exact local keys, its test runner):
//   repoContext / db / actors  → APPENDED after the preset text (preset safety guidance is kept)
//   inventorySql / inventoryFlagHint / testCmd / emitTestHint → REPLACE the preset field
//   lenses → replace the lens set · extraLenses → appended to it
//
// A RepoProbe passed to detect() is a plain object the controller fills in Stage 0:
//   { deps: {...package.json deps}, files: [relative paths present], manifests: {...} }
// ────────────────────────────────────────────────────────────────────────────────────


// Parse the Workflow `args` / `cfg` defensively. The Workflow tool sometimes delivers a nested
// object as a STRINGIFIED JSON (a documented quirk), so `args.cfg` can arrive as a string —
// which silently made `const CFG = args?.cfg || {}` see `{}` and drop cfg.preset, falling back
// to the blind generic adapter. This accepts cfg whether it's an object or a JSON string, and
// also unwraps a top-level stringified `args`. Returns a plain cfg object (never throws).
function parseWorkflowCfg(args) {
  let a = args
  if (typeof a === 'string') { try { a = JSON.parse(a) } catch (_) { a = {} } }
  let cfg = a && a.cfg
  if (typeof cfg === 'string') { try { cfg = JSON.parse(cfg) } catch (_) { cfg = {} } }
  return cfg && typeof cfg === 'object' ? cfg : {}
}

const DEFAULT_LENSES = [
  { key: 'authz', prompt: 'AUTHZ / access-policy lens. Using the inventory: any privileged operation (an admin-only handler, an elevated-privilege function, a job trigger) reachable by an unauthenticated or non-member caller with caller-controlled ids and no internal membership/role check (an access rule that defaults to open — no explicit deny — IS open); any UPDATE path that guards the row it reads but not the row it writes (destructive columns unguarded); ownership/tenancy/entitlement fields a permitted user can change. Cite the missing check.' },
  { key: 'input', prompt: 'INPUT-VALIDATION lens. Every action/route/webhook input validated? Mass-assignment (spreading raw user input into an update/insert without a column allowlist), queries built from raw user input (injection). Cite it.' },
  { key: 'tenant-scope', prompt: 'CROSS-OBJECT / TENANT-SCOPING lens. Every user-supplied id acted on without a membership/ownership check reached BEFORE the write; a write path that validates only user_id/created_by and omits the tenancy re-check its sibling paths carry.' },
  { key: 'billing', prompt: 'BILLING / ENTITLEMENT lens (skip if N/A). Paid features reachable by a non-payer or gated tenant; a gate on only some write paths; destructive lifecycle jobs that over-select or skip a blocker re-check; billing/PII fields readable by non-admins.' },
  { key: 'secrets-cron', prompt: 'SECRETS / CRON / EXTERNAL lens. Shared-secret checks constant-time + fail-closed + no user input; webhook signatures verified; no secret in the client bundle; server-side fetch of a user-supplied URL restricted to an allowlist (SSRF); privileged maintenance jobs callable by the wrong actor.' },
  { key: 'happy-path', prompt: 'FUNCTIONAL HAPPY-PATH lens. Enumerate every step of the user story (each CTA/route/state); flag any step whose wiring is missing or dead.' },
]

// The generic fallback — used when no preset matches and the user has not supplied one.
// Every field is an INSTRUCTION to the running agent to adapt to whatever stack is present.
// livefire degrades to this rather than failing; it also drives the interview that offers to
// save a livefire.config.js. It is deliberately stack-neutral (no Postgres assumptions).
const GENERIC_ADAPTER = {
  id: 'generic',
  repoContext: 'Adapt: describe the app, its multi-tenant/ownership model, and what a "wrong actor" is here.',
  db: 'Adapt: how to reach the live LOCAL / disposable store and an admin/superuser client for planting fixtures + the confirming ground-truth read. If there is no DB, name the durable store you can read directly to confirm a write landed.',
  actors: 'Adapt: how to construct the three attacker positions — (1) ANON: no session; (2) OUTSIDER: authenticated with zero membership in the target tenant; (3) INSIDER-WRONG-ROLE: authenticated plain member / non-owner. Plus the admin client for planting + the confirming read.',
  // NEVER blind on a Postgres target: probe first, and if it's Postgres, dump the full catalog
  // with the SAME SQL the supabase preset uses (that's what keeps a fallen-back generic run
  // equivalent to the supabase-native harness — the divergence was generic returning policies:0).
  inventorySql: 'Enumerate the app\'s authorization model as data. FIRST probe the DB: run `SELECT 1 FROM pg_catalog.pg_proc LIMIT 1`. IF it succeeds (a Postgres target), dump the FULL Postgres catalog:\n' + POSTGRES_INVENTORY_SQL + '\nOTHERWISE (no Postgres / authz in code): enumerate every route -> its guard and every data query missing a tenant/owner filter, and say the DB-grant dump is n/a for this stack.',
  inventorySchema: GENERIC_INVENTORY_SCHEMA,
  inventoryFlagHint: POSTGRES_INVENTORY_FLAG_HINT + ' (for a non-Postgres target, instead flag every route/unit a wrong actor reaches with no guard.)',
  inventoryExecution: 'If the target is Postgres: ' + POSTGRES_INVENTORY_EXECUTION + '\nOtherwise: ' + '• Run each enumeration step independently so one expected error never truncates the rest; retry a failed step standalone.',
  testCmd: 'Adapt: the project test runner.',
  lenses: DEFAULT_LENSES,
  emitTestHint: 'Adapt: write the regression test in the project\'s framework and PAIR the assertion with a direct ground-truth read (bypassing the app\'s own authz) so the test proves the row changed, not that a 200 returned.',
}

// Stack-neutral defaults for the optional instruction fields (used by every preset that does not
// override them). The pipeline reads these instead of naming any stack's tooling itself.
const DEFAULT_INVENTORY_EXECUTION =
  '• Run each enumeration step INDEPENDENTLY (one command / query / file scan at a time) so an expected error in one step never truncates the rest; retry a failed step standalone rather than dropping it.\n' +
  '• Count mechanically before you enumerate (e.g. the number of route registrations, rule blocks, permission rows) and report it in catalog_counts — your lists must match that count.'
const DEFAULT_GUARD_EXAMPLES =
  'a route middleware / auth guard, a policy or permission check (decorator, policy object, permission class), an ownership / tenant filter in the query itself, a DB-level row policy or grant, a trigger or constraint, a preceding role check, a webhook signature, a constant-time secret compare, a field allowlist'
const DEFAULT_CREDENTIALS_HINT =
  'take them from the local environment only (the local stack\'s own config / a .env or test env that points at the validated local host)'
const DEFAULT_SCOPE_UNITS = 'every privileged function, every access policy, every route'
const DEFAULT_PROVER_TARGETS =
  'every privileged unit, every write/read path, and every scheduled job in the inventory'

const OVERRIDE_APPEND = ['repoContext', 'db', 'actors']
const OVERRIDE_REPLACE = ['inventorySql', 'inventoryFlagHint', 'testCmd', 'emitTestHint', 'inventoryExecution', 'guardExamples', 'credentialsHint', 'proverTargets', 'scopeUnits']

// Resolve which adapter to use, in priority order:
//   1. cfg.adapter    — an explicit adapter object (highest precedence)
//   2. cfg.preset     — a preset id looked up in `registry`
//   3. auto-detect    — first registry preset whose detect(repoProbe) returns true
//   4. GENERIC_ADAPTER — the adapt-in-place fallback (drives the interview)
// Returns { adapter, source } so the controller can report how it was chosen and, when the
// source is 'generic', offer to save a livefire.config.js after the run.
function resolveAdapter(cfg = {}, registry = {}, repoProbe = null) {
  const pick = () => {
    // An inline adapter whose id names a shipped preset means "that preset + these tweaks".
    if (cfg.adapter && typeof cfg.adapter === 'object') {
      const base = cfg.adapter.id && registry[cfg.adapter.id]
      return { adapter: mergeDefaults(base ? { ...base, ...cfg.adapter } : cfg.adapter), source: 'explicit' }
    }
    if (cfg.preset && registry[cfg.preset]) return { adapter: mergeDefaults(registry[cfg.preset]), source: 'preset:' + cfg.preset }
    if (repoProbe) {
      for (const id of Object.keys(registry)) {
        const a = registry[id]
        try { if (typeof a.detect === 'function' && a.detect(repoProbe)) return { adapter: mergeDefaults(a), source: 'auto-detect:' + id } } catch (_) { /* a broken detect never blocks resolution */ }
      }
    }
    return { adapter: mergeDefaults(GENERIC_ADAPTER), source: 'generic' }
  }
  const r = pick()
  return { adapter: applyOverrides(r.adapter, cfg), source: r.source }
}

// Layer a project's own knowledge (cfg / livefire.config.mjs) over the resolved adapter. This is
// what verify-feature's controller always did at launch (the app's tenancy model, its local
// keys, `npx vitest run`) and what a preset alone cannot know.
function applyOverrides(adapter, cfg = {}) {
  const out = { ...adapter }
  const applied = []
  for (const k of OVERRIDE_APPEND) {
    if (typeof cfg[k] === 'string' && cfg[k].trim()) {
      // Project text is appended; for the fields that touch the store, the local-only rule is
      // restated AFTER it so a project note can never have the last word on credentials/targets.
      const reminder = k === 'repoContext' ? '' : '\n(Whatever the project text says: local/disposable targets and local credentials only — see the safety rules.)'
      out[k] = `${adapter[k]}\nPROJECT-SPECIFIC (${k}): ${cfg[k]}${reminder}`
      applied.push(k)
    }
  }
  for (const k of OVERRIDE_REPLACE) {
    if (typeof cfg[k] === 'string' && cfg[k].trim()) { out[k] = cfg[k]; applied.push(k) }
  }
  const validLens = (l) => l && typeof l === 'object' && typeof l.key === 'string' && l.key && typeof l.prompt === 'string' && l.prompt
  if (Array.isArray(cfg.lenses) && cfg.lenses.some(validLens)) { out.lenses = cfg.lenses.filter(validLens); applied.push('lenses') }
  if (Array.isArray(cfg.extraLenses) && cfg.extraLenses.length) {
    const keys = new Set(out.lenses.map((l) => l.key))
    out.lenses = out.lenses.concat(cfg.extraLenses.filter((l) => validLens(l) && !keys.has(l.key)))
    applied.push('extraLenses')
  }
  out.overridden = applied
  return out
}

// Fill any field a preset omitted from the generic defaults, so the pipeline can read every
// field unconditionally. lenses default to DEFAULT_LENSES; the rest to the generic instruction.
function mergeDefaults(a) {
  return {
    id: a.id || 'custom',
    detect: a.detect,
    repoContext: a.repoContext || GENERIC_ADAPTER.repoContext,
    db: a.db || GENERIC_ADAPTER.db,
    actors: a.actors || GENERIC_ADAPTER.actors,
    inventorySql: a.inventorySql || GENERIC_ADAPTER.inventorySql,
    inventorySchema: a.inventorySchema || GENERIC_ADAPTER.inventorySchema,
    testCmd: a.testCmd || GENERIC_ADAPTER.testCmd,
    lenses: a.lenses || DEFAULT_LENSES,
    emitTestHint: a.emitTestHint || GENERIC_ADAPTER.emitTestHint,
    inventoryFlagHint: a.inventoryFlagHint || 'Flag every unit reachable by a wrong actor without a guard, every write path that guards its read but not its write, and every secret/PII field readable beyond its owner.',
    inventoryExecution: a.inventoryExecution || DEFAULT_INVENTORY_EXECUTION,
    guardExamples: a.guardExamples || DEFAULT_GUARD_EXAMPLES,
    credentialsHint: a.credentialsHint || DEFAULT_CREDENTIALS_HINT,
    proverTargets: a.proverTargets || DEFAULT_PROVER_TARGETS,
    scopeUnits: a.scopeUnits || DEFAULT_SCOPE_UNITS,
  }
}


// ════════════════════════ inlined: src/prover-rules.js ════════════════════════
// livefire — the rules every agent that MUTATES the store must follow (prover, gap-closer, and
// the single-agent mode). One source, so the Workflow and single-agent modes can never drift.
// Stack-neutral: stack specifics arrive through the adapter (credentialsHint).

function proverRules(A) {
  return (
  `⚠️ SAFETY — before ANY mutation: confirm the DB host resolves to a LOCAL / disposable target (loopback 127.0.0.0/8 / ::1, localhost, *.local/.internal/.test, host.docker.internal, or an explicitly allow-listed host). If the host looks managed/production (a managed cloud DB such as *.supabase.co, *.rds.amazonaws.com, *.neon.tech, *.mongodb.net, *.firebaseio.com / a live Firebase project, a public domain, any routable IP, or contains "prod"), STOP: do NOT plant or delete anything, set degraded=true, and report "refused: non-local DB target". The controller has already run this check with livefire's guard (src/safety.js assertLocalDbTarget); you are the second line of defense — never mutate a non-local store.\n\n` +
  `⚠️ CREDENTIALS — use ONLY the LOCAL stack's keys/connection: ${A.credentialsHint}. NEVER use a production/managed credential even if you find one (an admin key or DB URL in a \`.env\` may point at prod). Do not print full secret values in the report — reference them by name.\n` +
  `⚠️ ENVIRONMENT IDENTITY — before the FIRST mutation, POSITIVELY PROVE you are in a test/disposable environment, not staging-by-accident or prod: (a) the admin client's URL/host must equal the local/allow-listed host you validated in the safety step; (b) for token-based stacks (JWT API keys), the environment the key names — its issuer / project id / audience claim — MUST match that host: decode the token and compare; a key issued for a different environment is the WRONG environment → STOP; (c) run a READ-ONLY canary first and sanity-check it's disposable data (e.g. it's the local seed / an allow-listed test project, not live production volumes) — a plausibility check on a known table before any write. If you cannot positively confirm the target is a test/disposable store whose credentials match it, set degraded=true and do NOT mutate.\n\n` +
  `⚠️ SEED LEDGER + CLEANUP — keep a ledger of EVERY row you insert (table + primary key + a recognizable marker, e.g. a "livefire_test_<runid>" value in a text field). Delete ONLY the exact rows in your ledger, by primary key — NEVER a broad DELETE by predicate (you could wipe real data). Also delete any rows YOUR exploits caused to be written. Default is to clean up automatically at the end (leave no residue, especially on a shared/allow-listed host). After the report the controller may ask the user whether to KEEP the seed data instead (opt-out) — until told to keep it, remove it. If any cleanup fails, DO NOT hide it: return the residual ledger (what remains + where) so it can be removed by hand. Note in the report that on a non-local host, mutations may have fired external side-effects (emails, webhooks, billing) that deleting rows does NOT undo.`
  )
}


// ════════════════════════ inlined: src/budget.js ════════════════════════
// Fan-out guards for the pipeline — born from incident wf_7418b0da (2026-09-23): the sweep loop
// re-swept every "new" family, but a family is FREE TEXT written by each verifier, so every
// sibling invented a variant ("… (org-keyed arm)", "… (helper-predicate arm)") and the
// run spent 1000 agents / 90.5M tokens before the runtime's hard cap stopped it.
//
// Two guards live here, both pure (no runtime globals) so they are unit-testable and inlined by
// build.mjs ahead of the pipeline body:
//   canonFamily      — one key per root-cause family, whatever the verifier's wording
//   makeAgentBudget  — a per-stage + total agent budget that DROPS (and logs) past the cap,
//                      so no stage can reach the runtime's 1000-agent ceiling

// Lowercase, drop every parenthetical note, keep the first "A / B" segment, slug the rest.
function canonFamily(family) {
  if (typeof family !== 'string') return ''
  let s = family.toLowerCase()
  // strip innermost parentheticals repeatedly (handles nesting), then any unbalanced tail
  for (let prev = null; prev !== s;) { prev = s; s = s.replace(/\([^()]*\)/g, ' ') }
  s = s.replace(/\(.*$/, ' ')
  s = s.split(/\s\/\s|;/)[0]
  return s.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
}

const DEFAULT_PER_STAGE = 120
const DEFAULT_TOTAL = 400
// Stay well below the Workflow runtime's hard cap of 1000 agent() calls.
const MAX_TOTAL = 900

function positiveInt(v) {
  if (v === null || v === '' || typeof v === 'boolean') return null
  const n = Number(v)
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : null
}

// cfg.maxAgents = per-stage cap, cfg.maxAgentsTotal = whole-run cap. Invalid → default, never "no cap".
function parseAgentCaps(cfg) {
  const c = cfg || {}
  return {
    perStage: positiveInt(c.maxAgents) ?? DEFAULT_PER_STAGE,
    total: Math.min(MAX_TOTAL, positiveInt(c.maxAgentsTotal) ?? DEFAULT_TOTAL),
  }
}

// Wraps the runtime's agent(). The counter moves at CALL time (synchronously), so a parallel()
// burst is capped exactly. A dropped call returns null — every call site already treats null as
// "no answer" (parallel results are filtered with Boolean; direct awaits check !x).
function makeAgentBudget(agentFn, caps, logFn) {
  const perStage = {}
  const dropped = []
  let total = 0
  const stageOf = (opts) => (opts && opts.phase) || 'Setup'
  const remaining = (stage) => Math.max(0, Math.min(caps.perStage - (perStage[stage] || 0), caps.total - total))
  async function agent(prompt, opts) {
    const stage = stageOf(opts)
    if (remaining(stage) <= 0) {
      const label = (opts && opts.label) || '?'
      dropped.push({ stage, label })
      logFn(`⚠️ agent budget: dropped ${label} (stage ${stage} ${perStage[stage] || 0}/${caps.perStage}, total ${total}/${caps.total})`)
      return null
    }
    perStage[stage] = (perStage[stage] || 0) + 1
    total++
    return agentFn(prompt, opts)
  }
  return {
    agent,
    remaining,
    report: () => ({ caps: { per_stage: caps.perStage, total: caps.total }, per_stage: { ...perStage }, total, dropped: dropped.slice() }),
  }
}


// ════════════════════════ inlined: src/inventory-view.js ════════════════════════
// How the live inventory is shown to the agents (W4.3 a, 2026-09-26). Pure, stack-agnostic, and
// inlined by build.mjs ahead of the pipeline body.
//
//   both    — DEFAULT (2026-09-27): every static lens runs once per view and the candidates are
//             merged; prover and sweep get the full view. Measured on a production Next.js + Supabase app: the full view
//             found 14 highs but 1 app-tier hole, the compact view 9 highs but 10 app-tier holes.
//   full    — the pretty JSON, exactly as before
//   compact — every item still listed, one line each, long strings truncated (57.6k → 39.5k
//             chars on that app). The full dump pulls reviewer attention to the data tier;
//             the compact one leaves room for the app tier. Not a cost saving (~4%).

const MAX_FIELD = 160

// both (default since 2026-09-27) = the static lenses run once per view; full / compact = one view.
function parseInventoryMode(cfg) {
  const m = cfg && typeof cfg.inventoryMode === 'string' ? cfg.inventoryMode.trim().toLowerCase() : ''
  return m === 'full' || m === 'compact' ? m : 'both'
}

function cut(v) {
  const s = typeof v === 'string' ? v : JSON.stringify(v)
  return s.length > MAX_FIELD ? s.slice(0, MAX_FIELD) + '…' : s
}

function line(item) {
  if (!item || typeof item !== 'object') return '- ' + cut(item)
  const parts = Object.entries(item).filter(([, v]) => v !== '' && v !== null && v !== undefined).map(([k, v]) => `${k}=${cut(v)}`)
  return '- ' + parts.join(' · ')
}

function renderInventory(inv, mode) {
  if (mode !== 'compact') return JSON.stringify(inv, null, 2)
  const out = [`(compact view: every item is listed, but text longer than ${MAX_FIELD} chars is truncated with "…". When a truncated line matters to your judgement, read its full definition from the live store or the source before concluding.)`]
  for (const [k, v] of Object.entries(inv || {})) {
    if (Array.isArray(v)) {
      out.push(`${k} (${v.length}):`)
      for (const it of v) out.push(line(it))
    } else {
      out.push(`${k}: ${JSON.stringify(v)}`)
    }
  }
  return out.join('\n')
}


